const V='red-quiz-v1';self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(['./','./index.html','./styles.css','./app.js','./knowledge.json','./manifest.webmanifest',...["./assets/icon-192.png","./assets/icon-512.png","./assets/image-1.png","./assets/image-2.png","./assets/image-3.png","./assets/image-4.png","./assets/image-5.png","./assets/image-6.png","./assets/image-7.png","./assets/image-8.png","./assets/image-9.png","./assets/image.png"]])).then(()=>self.skipWaiting()).catch(()=>{}))});self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>e.respondWith(caches.match(e.request).then(x=>x||fetch(e.request).then(r=>{if(r.ok){const z=r.clone();caches.open(V).then(c=>c.put(e.request,z))}return r}).catch(()=>caches.match('./index.html')))));